import React, { Component } from 'react';
import axios from 'axios';
import MyContext from '../contexts/MyContext';

class Category extends Component {
  static contextType = MyContext;

  constructor(props) {
    super(props);
    this.state = {
      categories: [],
      txtID: '',
      txtName: '',
      txtSortOrder: 0,
      cmbStatus: 'Active',
      isEdit: false
    };
  }

  componentDidMount() {
    this.apiGetCategories();
  }

  // API lấy danh sách danh mục
  apiGetCategories = () => {
    const config = { headers: { 'x-access-token': this.context.token } };
    axios.get('/api/admin/categories', config).then((res) => {
      this.setState({ categories: res.data });
    });
  };

  // Chọn danh mục từ bảng để chỉnh sửa
  selectItem = (item) => {
    this.setState({
      txtID: item._id,
      txtName: item.name,
      txtSortOrder: item.sortOrder || 0,
      cmbStatus: item.status || 'Active',
      isEdit: true
    });
  };

  // Làm mới Form
  resetForm = () => {
    this.setState({
      txtID: '',
      txtName: '',
      txtSortOrder: 0,
      cmbStatus: 'Active',
      isEdit: false
    });
  };

  // Thêm mới hoặc Cập nhật
  btnSaveClick = (e) => {
    e.preventDefault();
    const { txtID, txtName, txtSortOrder, cmbStatus, isEdit } = this.state;
    if (!txtName) {
      alert('Vui lòng nhập tên danh mục!');
      return;
    }

    const category = { name: txtName, sortOrder: parseInt(txtSortOrder), status: cmbStatus };
    const config = { headers: { 'x-access-token': this.context.token } };

    if (isEdit) {
      axios.put(`/api/admin/categories/${txtID}`, category, config).then((res) => {
        if (res.data) {
          alert('Cập nhật danh mục thành công!');
          this.apiGetCategories();
          this.resetForm();
        }
      });
    } else {
      axios.post('/api/admin/categories', category, config).then((res) => {
        if (res.data) {
          alert('Thêm danh mục mới thành công!');
          this.apiGetCategories();
          this.resetForm();
        }
      });
    }
  };

  // Xóa danh mục
  btnDeleteClick = (id) => {
    if (window.confirm('Bạn có chắc muốn xóa danh mục này?')) {
      const config = { headers: { 'x-access-token': this.context.token } };
      axios.delete(`/api/admin/categories/${id}`, config).then((res) => {
        if (res.data.success) {
          alert('Đã xóa thành công!');
          this.apiGetCategories();
          this.resetForm();
        }
      });
    }
  };

  render() {
    const { categories, txtName, txtSortOrder, cmbStatus, isEdit } = this.state;

    return (
      <div style={{ padding: '20px' }}>
        <h3 style={{ color: '#4A2E2B', marginBottom: '20px' }}>QUẢN LÝ DANH MỤC THỰC ĐƠN</h3>
        <div style={{ display: 'flex', gap: '30px' }}>
          
          {/* Cột trái: Form nhập thông tin */}
          <div style={{ flex: '1', backgroundColor: '#FFF', padding: '20px', borderRadius: '12px', boxShadow: '0 2px 8px rgba(0,0,0,0.05)' }}>
            <h4 style={{ marginBottom: '15px' }}>{isEdit ? 'Chỉnh sửa danh mục' : 'Thêm danh mục mới'}</h4>
            <form>
              <div style={{ marginBottom: '15px' }}>
                <label style={{ display: 'block', marginBottom: '5px' }}>Tên danh mục *</label>
                <input
                  type="text"
                  style={{ width: '100%', padding: '8px', borderRadius: '6px', border: '1px solid #ccc' }}
                  value={txtName}
                  onChange={(e) => this.setState({ txtName: e.target.value })}
                  placeholder="VD: Món chính, Đồ uống..."
                />
              </div>

              <div style={{ marginBottom: '15px' }}>
                <label style={{ display: 'block', marginBottom: '5px' }}>Thứ tự hiển thị</label>
                <input
                  type="number"
                  style={{ width: '100%', padding: '8px', borderRadius: '6px', border: '1px solid #ccc' }}
                  value={txtSortOrder}
                  onChange={(e) => this.setState({ txtSortOrder: e.target.value })}
                />
              </div>

              <div style={{ marginBottom: '20px' }}>
                <label style={{ display: 'block', marginBottom: '5px' }}>Trạng thái</label>
                <select
                  style={{ width: '100%', padding: '8px', borderRadius: '6px', border: '1px solid #ccc' }}
                  value={cmbStatus}
                  onChange={(e) => this.setState({ cmbStatus: e.target.value })}
                >
                  <option value="Active">Hoạt động (Active)</option>
                  <option value="Inactive">Tạm ẩn (Inactive)</option>
                </select>
              </div>

              <div style={{ display: 'flex', gap: '10px' }}>
                <button
                  type="submit"
                  onClick={this.btnSaveClick}
                  style={{ flex: 1, backgroundColor: '#4A2E2B', color: '#FFF', padding: '10px', border: 'none', borderRadius: '6px', cursor: 'pointer' }}
                >
                  {isEdit ? 'CẬP NHẬT' : 'LƯU DANH MỤC'}
                </button>
                {isEdit && (
                  <button
                    type="button"
                    onClick={this.resetForm}
                    style={{ backgroundColor: '#888', color: '#FFF', padding: '10px', border: 'none', borderRadius: '6px', cursor: 'pointer' }}
                  >
                    HỦY
                  </button>
                )}
              </div>
            </form>
          </div>

          {/* Cột phải: Bảng danh sách danh mục */}
          <div style={{ flex: '2', backgroundColor: '#FFF', padding: '20px', borderRadius: '12px', boxShadow: '0 2px 8px rgba(0,0,0,0.05)' }}>
            <h4 style={{ marginBottom: '15px' }}>Danh sách danh mục hiện có</h4>
            <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left' }}>
              <thead>
                <tr style={{ backgroundColor: '#F4EBE1', borderBottom: '2px solid #DDD' }}>
                  <th style={{ padding: '10px' }}>STT</th>
                  <th style={{ padding: '10px' }}>Tên danh mục</th>
                  <th style={{ padding: '10px' }}>Số món</th>
                  <th style={{ padding: '10px' }}>Trạng thái</th>
                  <th style={{ padding: '10px' }}>Hành động</th>
                </tr>
              </thead>
              <tbody>
                {categories.map((item, index) => (
                  <tr key={item._id} style={{ borderBottom: '1px solid #EEE' }}>
                    <td style={{ padding: '10px' }}>{index + 1}</td>
                    <td style={{ padding: '10px', fontWeight: 'bold' }}>{item.name}</td>
                    <td style={{ padding: '10px' }}>{item.sortOrder || 0}</td>
                    <td style={{ padding: '10px' }}>
                      <span style={{
                        padding: '4px 8px', borderRadius: '12px', fontSize: '12px', color: '#FFF',
                        backgroundColor: item.status === 'Active' ? '#2E7D32' : '#C62828'
                      }}>
                        {item.status || 'Active'}
                      </span>
                    </td>
                    <td style={{ padding: '10px' }}>
                      <button
                        onClick={() => this.selectItem(item)}
                        style={{ marginRight: '8px', backgroundColor: '#C85A32', color: '#FFF', border: 'none', padding: '4px 10px', borderRadius: '4px', cursor: 'pointer' }}
                      >
                        Sửa
                      </button>
                      <button
                        onClick={() => this.btnDeleteClick(item._id)}
                        style={{ backgroundColor: '#D32F2F', color: '#FFF', border: 'none', padding: '4px 10px', borderRadius: '4px', cursor: 'pointer' }}
                      >
                        Xóa
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>

        </div>
      </div>
    );
  }
}

export default Category;
